// Friendly names for the API's response shapes. The shapes themselves come from the backend's
// OpenAPI spec (trips.d.ts, generated by `npm run api:types` — never hand-edit).
import type { components as TripsComponents } from './trips';

type TripsSchemas = TripsComponents['schemas'];

export type Trip = TripsSchemas['TripView'];
export type TripList = TripsSchemas['TripList'];
export type TripDay = TripsSchemas['TripDayView'];
export type Stop = TripsSchemas['StopView'];
export type Stay = TripsSchemas['StayView'];
export type Booking = TripsSchemas['BookingView'];
export type Place = TripsSchemas['PlaceView'];
